declare namespace React {
  type Key = string | number;
  type ReactNode = string | number | boolean | null | undefined | ReactElement;

  interface Attributes {
    key?: Key | null | undefined;
  }

  interface Ref<T> {
    current: T | null;
  }

  interface RefAttributes<T> extends Attributes {
    ref?: Ref<T> | null | undefined;
  }

  interface ReactElement<P = any, T = any> {
    type: T;
    props: P;
    key: Key | null;
  }

  interface FunctionComponent<P = {}> {
    (props: P): ReactNode;
    displayName?: string | undefined;
  }

  interface NamedExoticComponent<P = {}> {
    (props: P): ReactNode;
    displayName?: string | undefined;
  }

  interface ForwardRefExoticComponent<P> extends NamedExoticComponent<P> {}

  interface MemoExoticComponent<T> extends NamedExoticComponent<ComponentProps<T>> {
    readonly type: T;
  }

  type ComponentType<P = {}> = FunctionComponent<P>;
  type ElementType<P = any> = keyof JSX.IntrinsicElements | ComponentType<P>;
  type ComponentProps<T extends ElementType> =
    T extends keyof JSX.IntrinsicElements ? JSX.IntrinsicElements[T] : any;
  type ComponentPropsWithRef<T extends ElementType> =
    ComponentProps<T> & RefAttributes<any>;
  type ComponentRef<T extends ElementType> = Ref<any>;
  type ElementRef<C extends ElementType> = ComponentRef<C>;
  type LibraryManagedAttributes<C, P> = P;

  namespace JSX {
    interface Element extends ReactElement<any, any> {}

    interface IntrinsicElements {
      div: DOMAttributes;
      button: ButtonHTMLAttributes;
    }

    type LibraryManagedAttributes<C, P> =
      React.LibraryManagedAttributes<C, P>;
  }

  interface DOMAttributes {
    id?: string | undefined;
    children?: ReactNode | undefined;
  }

  interface ButtonHTMLAttributes extends DOMAttributes {
    disabled?: boolean | undefined;
  }

  function createElement(
    type: "input",
    props?: DOMAttributes | null,
    ...children: ReactNode[]
  ): ReactElement<DOMAttributes, string>;
  function createElement(
    type: keyof JSX.IntrinsicElements,
    props?: DOMAttributes | null,
    ...children: ReactNode[]
  ): ReactElement<DOMAttributes, string>;

  function cloneElement(
    element: ReactElement<any>,
    props?: any,
    ...children: ReactNode[]
  ): ReactElement<any>;
  function cloneElement(
    element: ReactElement<DOMAttributes>,
    props?: Partial<DOMAttributes> | null,
    ...children: ReactNode[]
  ): ReactElement<DOMAttributes>;

  function forwardRef<T, P = {}>(
    render: (props: P, ref: Ref<T>) => ReactNode
  ): ForwardRefExoticComponent<P & RefAttributes<T>>;

  function memo<P extends object>(
    Component: FunctionComponent<P>,
    propsAreEqual?: (prevProps: Readonly<P>, nextProps: Readonly<P>) => boolean
  ): MemoExoticComponent<FunctionComponent<P>>;

  function normalizeProps(
    props: LibraryManagedAttributes<
      FunctionComponent<ComponentProps<"button">>,
      ComponentProps<"button">
    >
  ): ComponentProps<"button">;

  function useComponentRef(ref: ComponentRef<"button">): ElementRef<"button">;
}

export = React;
export as namespace React;
